package com.primehr.security;import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;class RrAwardPermissionGuardTest{@Test void fulfillmentAndAgencyReportActionsRemainIndependent(){var client=mock(AdministrativeAuthorizationClient.class);var guard=new RrAwardPermissionGuard(client);when(client.resolve(RrAwardPermissionGuard.FULFILLMENT,"t")).thenReturn(new EffectiveFeaturePermission("f",false,true,true,true,false,false,true,false,false,false,false,PermissionDataScope.ASSIGNED_RECORDS));assertThat(guard.require(RrAwardPermissionGuard.FULFILLMENT,PrimeHrAction.ADD,"t")).isEqualTo(PermissionDataScope.ASSIGNED_RECORDS);assertThatThrownBy(()->guard.require(RrAwardPermissionGuard.FULFILLMENT,PrimeHrAction.APPROVE,"t")).isInstanceOf(AccessDeniedException.class);when(client.resolve(RrAwardPermissionGuard.REPORT,"t")).thenReturn(new EffectiveFeaturePermission("f",false,true,false,false,false,false,false,false,false,false,false,PermissionDataScope.ASSIGNED_RECORDS));assertThatThrownBy(()->guard.requireAgency(RrAwardPermissionGuard.REPORT,PrimeHrAction.ACCESS,"t")).isInstanceOf(AccessDeniedException.class);}}
